let grid: Int16Array | null = null;
function cells(): Int16Array {
  if (grid) return grid;
  const bin = Uint8Array.from(atob(B64), c => c.charCodeAt(0));
  grid = new Int16Array(bin.buffer, bin.byteOffset, bin.byteLength / 2);
  return grid;
}
export const COARSE_N = 256;
let enabled = true;
/** Tests turn this off to read the seeded mountain the drop used to stand on. */
export function coarseReliefOn(v?: boolean) {
  if (v !== undefined) enabled = v;
  return enabled;
}
/** Metres, nearest zoom-0 pixel. Latitude is clamped to the Web Mercator range, as slippy does. */
export function coarseMetres(latDeg: number, lonDeg: number): number {
  const n = COARSE_N;
  const x = ((lonDeg + 180) / 360) * n;
  const lat = Math.max(-85, Math.min(85, latDeg)) * Math.PI / 180;
  const y = (1 - Math.log(Math.tan(lat) + 1 / Math.cos(lat)) / Math.PI) / 2 * n;
  const ix = Math.floor(x) % n;
  const iy = Math.min(n - 1, Math.max(0, Math.floor(y)));
  const wrapped = (ix + n) % n;
  return cells()[iy * n + wrapped];
}
